def calculate_average_monthly_savings(income, expenses):
    if len(income) != len(expenses) or len(income) != 12 or len(expenses) != 12:
        return None

    total_savings = 0
    for i in range(12):
        monthly_income = income[i]
        monthly_expense = expenses[i]
        if not isinstance(monthly_income, (int, float)) or not isinstance(monthly_expense, (int, float)):
            return None
        if monthly_income < 0 or monthly_expense < 0:
            return None
        monthly_savings = monthly_income - monthly_expense
        if monthly_savings < 0:
            return None
        total_savings += monthly_savings

    average_savings = total_savings / 12
    return average_savings

